import type { Browser, BrowserContext, BrowserContextOptions, Page } from 'playwright-core';
import { visualRequestPolicy, visualSeedTime } from './visual-request-policy.js';
const languageStorageKey = 'together-language';
const placeholderPng = Buffer.from(
  '',
  'base64',
);

const stubNonDeterministicRequests = async (context: BrowserContext): Promise<void> => {
  await context.route('**/*', (route) => {
    const policy = visualRequestPolicy(new URL(route.request().url()), route.request().resourceType());
    if (policy === 'abort') return route.abort();
    if (policy === 'continue') return route.continue();
    return route.fulfill({ contentType: 'image/png', body: placeholderPng });
  });
};

export const applyChrome = async (context: BrowserContext): Promise<void> => {
  await context.addInitScript(
    (langKey) => {
      // Capture waits must observe compositor frames even after Playwright installs its clock.
      const nativeFrame = window.requestAnimationFrame.bind(window);
      window.addEventListener('visual:paint-request', () => {
        nativeFrame(() => nativeFrame(() => window.dispatchEvent(new Event('visual:paint-ready'))));
      });
      Object.defineProperty(window, 'EventSource', { configurable: true, value: undefined });
      try {
        window.localStorage.setItem(langKey, 'en');
      } catch {
        // storage disabled — the choice simply won't persist
      }
    },
    languageStorageKey,
  );
};

export const waitForPaint = async (page: Page): Promise<void> => {
  await page.evaluate(() => new Promise<void>((resolve) => {
    window.addEventListener('visual:paint-ready', () => resolve(), { once: true });
    window.dispatchEvent(new Event('visual:paint-request'));
  }));
};

export const settlePage = async (page: Page, waitForNetworkIdle = true): Promise<void> => {
  if (waitForNetworkIdle) await page.waitForLoadState('networkidle');
  await page.evaluate(async () => {
    await document.fonts.ready;
    await Promise.all([...document.images].filter((image) => !image.complete || image.naturalWidth > 0).map((image) => image.decode()));
  });
  await page.addStyleTag({
    content: `
      *, *::before, *::after {
        animation: none !important;
        transition: none !important;
        caret-color: transparent !important;
      }
    `,
  });
  await waitForPaint(page);
};

export const createVisualCapture = async (
  browser: Browser,
  viewport: { width: number; height: number },
  storageState?: BrowserContextOptions['storageState'],
): Promise<{ context: BrowserContext; page: Page }> => {
  const context = await browser.newContext({
    viewport: { width: viewport.width, height: viewport.height },
    deviceScaleFactor: 1,
    colorScheme: 'light',
    locale: 'pl-PL',
    timezoneId: 'UTC',
    reducedMotion: 'reduce',
    ...(storageState === undefined ? {} : { storageState }),
  });
  await applyChrome(context);
  await stubNonDeterministicRequests(context);
  const page = await context.newPage();
  await page.clock.setFixedTime(new Date(visualSeedTime));
  return { context, page };
};
